<?php
namespace App\Jobs;
use App\Models\Transaction; use App\Services\Digiflazz\DigiflazzClient; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\SerializesModels;
class ProcessDigiflazzTransaction implements ShouldQueue { use Dispatchable,InteractsWithQueue,SerializesModels; public int $tries=3; public function __construct(public int $transactionId){} public function handle(DigiflazzClient $client):void{$trx=Transaction::with('product','order')->findOrFail($this->transactionId);if($trx->status!=='pending')return;$trx->update(['status'=>'processing']);$res=$client->transaction($trx->product->digiflazz_sku,$trx->target,$trx->digiflazz_ref_id);$status=strtolower(data_get($res,'data.status',data_get($res,'status','pending')));$map=['sukses'=>'success','success'=>'success','gagal'=>'failed','failed'=>'failed','pending'=>'processing'];$trx->update(['status'=>$map[$status]??'processing','serial_number'=>data_get($res,'data.sn',data_get($res,'sn')),'response'=>$res,'processed_at'=>now()]);$trx->order->update(['status'=>$trx->status,'payment_status'=>'paid']);} }
